import sys
from math import gcd

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    L = 1
    for x in a:
        L = L // gcd(L, x) * x
    pp = []
    m = L
    p = 2
    while p * p <= m:
        if m % p == 0:
            q = 1
            while m % p == 0:
                m //= p
                q *= p
            pp.append(q)
        p += 1 if p == 2 else 2
    if m > 1:
        pp.append(m)
    k = len(pp)
    full = (1 << k) - 1
    masks = set()
    for x in a:
        mk = 0
        for j, q in enumerate(pp):
            if x % q == 0:
                mk |= 1 << j
        masks.add(mk)
    INF = 10 ** 9
    dp = [INF] * (1 << k)
    dp[0] = 0
    for mk in masks:
        for s in range(1 << k):
            if dp[s] < INF:
                t = s | mk
                if dp[s] + 1 < dp[t]:
                    dp[t] = dp[s] + 1
    print(max(1, dp[full]))

main()

